-- Comidas con foto: equivalente en Postgres/Supabase de la migración EF "AddMeals".
-- Es idempotente: se puede volver a ejecutar (en Supabase la tabla "MealLogs" ya existe).

create table if not exists "MealLogs" (
  "Id" integer generated by default as identity primary key,
  "UserId" integer not null,
  "Date" timestamp without time zone not null,
  "Time" varchar(5) null,
  "MealType" varchar(20) null,
  "Note" varchar(500) null,
  "Photo" bytea null,
  "PhotoContentType" varchar(50) null,
  "Status" varchar(20) not null,
  "ItemsJson" text not null,
  "TotalCalories" double precision not null,
  "ProteinG" double precision null,
  "CarbsG" double precision null,
  "FatG" double precision null,
  "AnalysisNotes" varchar(1000) null,
  "CreatedAt" timestamp without time zone not null,
  "UpdatedAt" timestamp without time zone not null,
  "AnalyzedAt" timestamp without time zone null,
  "ConfirmedAt" timestamp without time zone null
);
create index if not exists "IX_MealLogs_UserId_Date" on "MealLogs" ("UserId", "Date");
create index if not exists "IX_MealLogs_UserId_Status" on "MealLogs" ("UserId", "Status");

-- Como el resto de tablas: RLS activado y sin políticas (la API de Compás usa un rol propietario).
alter table "MealLogs" enable row level security;
